try { jobId = $('Execute Webhook').first()?.json?.body?.job_id; } catch(e) {}
if (!jobId || jobId === 'unknown') { try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {} }

let iterations = 0;
try {
  let loops = $('Error Fixer Loop').all();
  iterations = loops ? loops.length : 0;
} catch(e) {}

let now = Date.now();
let workflowStart = now;
try { workflowStart = $('Init Telemetry').first().json.workflow_start; } catch(e) {}
let executionTimeMs = now - workflowStart;

let nodeExecutions = [];
let llmUsages = [];

function estimateTokens(textStr) {
    if (!textStr) return 0;
    return Math.ceil(textStr.length / 3.0);
}
// USD per 1K tokens (blended in/out estimate, OpenRouter list prices Sept 2026)
const MODEL_COSTS = {
  'deepseek/deepseek-v4.1-flash': 0.00034,
  'deepseek/deepseek-v4-flash-0731:floor': 0.00012,
  'z-ai/glm-5.3-flash': 0.00016,
  'meta-llama/llama-3.3-70b-instruct': 0.0003
};
function getCost(modelName) { return MODEL_COSTS[modelName] || 0.0002; }

function extractTokenUsage(agentNodeName, promptText, agentOutputJson) {
    let fallbackPromptTokens = estimateTokens(promptText);
    let outputText = typeof agentOutputJson === 'string' ? agentOutputJson : JSON.stringify(agentOutputJson);
    let fallbackCompletionTokens = estimateTokens(outputText);

    // Try to get tokenUsage from the Agent node directly natively
    try {
        let usage = $(agentNodeName).last().json.tokenUsage;
        if (usage && usage.promptTokens) {
            return {
                promptTokens: usage.promptTokens,
                completionTokens: usage.completionTokens || usage.completion_tokens || fallbackCompletionTokens,
                totalTokens: usage.totalTokens || usage.total_tokens || (usage.promptTokens + fallbackCompletionTokens)
            };
        }
    } catch(e) {}

    return { 
        promptTokens: fallbackPromptTokens, 
        completionTokens: fallbackCompletionTokens, 
        totalTokens: fallbackPromptTokens + fallbackCompletionTokens 
    };
}

try {
    let agentStart = $('Pre-Analyzer Agent Telemetry').first().json.agent_start;
    nodeExecutions.push({
        NodeName: 'Analyzer Agent',
        Phase: 'Phase 1',
        ExecutionTimeMs: now - agentStart
    });

    // Dynamically reconstruct the prompt string to estimate length
    let basePrompt = `Analyze the following .NET project files, Repository File Tree, and Roslyn Upgrade Assistant output.
Your task is to produce a complete .NET migration plan.
CRITICAL: NEVER include 'Microsoft.NETCore.App' or 'Microsoft.AspNetCore.App' in package_updates or nuget_versions_needed. These are framework implicit references, NOT NuGet packages, and trying to add them via CLI will cause execution failure.
CRITICAL: If the code uses .WithOpenApi(), you MUST add Microsoft.AspNetCore.OpenApi to package_updates with action "add".
CRITICAL: For Deprecated WebClient or RNGCryptoServiceProvider, you MUST put the replacement logic inside file_changes. The new code MUST be valid C# (e.g., use await HttpClient.GetStringAsync and change the method signature to async Task<IActionResult>). Do not put code changes in startup_changes if they require actual file modifications.
IMPORTANT: Do NOT output multiple overlapping ReplaceFileContent actions for the same file. If you need to make multiple changes to a single file, you MUST combine them into a single ReplaceFileContent action that replaces a larger block of code containing all your changes.
IMPORTANT: When specifying file paths in your plan, you MUST refer to the "REPOSITORY FILE TREE" in the input below. Use the EXACT full relative path shown there. Do NOT guess or hallucinate paths.
CRITICAL: Do NOT hallucinate files that do not exist in the repository. Always use Program.cs for configuration in .NET 6+.
CRITICAL: Extract the Source Framework from the csproj or Roslyn output. It is usually net6.0, net7.0, or netcoreapp3.1.
IMPORTANT: Your response MUST be valid JSON.
Every required property defined in the schema MUST be present.
estimated_changes MUST be an integer.
risk_level MUST be one of: low, medium, high.
action MUST be one of: update, remove, add, no_update.

Use these inputs:
- Repository File Tree & Roslyn Analysis
- Known Patterns`;

    let customPrompt = '';
    try { customPrompt = $('Webhook').first().json.body.custom_prompt || ''; } catch(e) {}

    let repoProfile = '';
    try { repoProfile = $('Webhook').first().json.body.repository_profile || '[]'; } catch(e) {}

    let roslynOutput = '';
    try { roslynOutput = ($('Pre-Analyzer Agent Telemetry').first().json.stdout || '').substring(0,8000); } catch(e) {}

    let knownPatterns = '';
    try { knownPatterns = ($('Load Known Patterns').first().json.known_patterns || '').substring(0,2000); } catch(e) {}

    let fullPrompt = basePrompt + customPrompt + repoProfile + roslynOutput + knownPatterns;

    let analyzerModel = 'qwen/qwen3-32b';
    try { analyzerModel = $evaluateExpression('{{ $node["Analyzer LLM"].parameter.model }}') || analyzerModel; } catch(e) {}

    let agentOutput = $('Analyzer Agent').first().json || {};
    let usage = extractTokenUsage('Analyzer Agent', fullPrompt, agentOutput);
    let cost = (usage.totalTokens / 1000) * getCost(typeof analyzerModel !== 'undefined' ? analyzerModel : 'qwen/qwen3-32b');

    llmUsages.push({
        AgentName: 'Analyzer Agent',
        ModelName: typeof analyzerModel !== 'undefined' ? analyzerModel : 'qwen/qwen3-32b',
        Provider: 'OpenRouter',
