return $input.all();

// Resolve the newest version of a NuGet package that is COMPATIBLE with a target framework.
// Uses the NuGet V3 registration hive (dependencyGroups[].targetFramework) + vulnerability data.
const pkg = String(query.packageId || '').trim();
const tfm = String(query.targetFramework || 'net8.0').trim().toLowerCase();

if (!pkg) return 'ERROR: packageId is required.';

const FRAMEWORK_REFS = ['microsoft.netcore.app', 'microsoft.aspnetcore.app', 'microsoft.windowsdesktop.app'];
if (FRAMEWORK_REFS.includes(pkg.toLowerCase())) {
  return `ERROR: ${pkg} is an implicit framework reference, not a NuGet package. Do not add it.`;
}

// Ordered compatibility fallback: a package group is usable if it is this TFM or anything below it.
const LADDER = {
  'net10.0': ['net10.0','net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net9.0':  ['net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net8.0':  ['net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net7.0':  ['net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net6.0':  ['net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0']
};
const allowed = LADDER[tfm] || LADDER['net8.0'];

function normTfm(s) {
  if (!s) return 'any';
  let t = String(s).toLowerCase().trim();
  if (t.startsWith('.netcoreapp,version=v')) t = 'net' + t.split('v')[1];
  else if (t.startsWith('.netstandard,version=v')) t = 'netstandard' + t.split('v')[1];
  else if (t.startsWith('.netframework,version=v')) t = 'netframework' + t.split('v')[1];
  return t.split('-')[0]; // drop platform suffix (net8.0-windows -> net8.0)
}

try {
  const reg = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.nuget.org/v3/registration5-gz-semver2/${pkg.toLowerCase()}/index.json`,
    json: true
  });

  // Flatten pages (inlined items, or fetch the page if not inlined)
  // Fetch all non-inlined registration pages in parallel instead of one at a time.
  const pages = await Promise.all((reg.items || []).map(async (page) => {
    if (page.items) return page.items;
    try {
      const p = await this.helpers.httpRequest({ method: 'GET', url: page['@id'], json: true });
      return p.items || [];
    } catch (e) { return []; }
  }));
  let entries = [];
  for (const items of pages) {
    for (const it of items) if (it.catalogEntry) entries.push(it.catalogEntry);
  }

  entries = entries.filter(e => e.listed !== false && !String(e.version).includes('-'));
  entries.sort((a, b) => {
    const pa = String(a.version).split('.').map(Number);
    const pb = String(b.version).split('.').map(Number);
    for (let i = 0; i < 4; i++) { if ((pa[i]||0) !== (pb[i]||0)) return (pb[i]||0) - (pa[i]||0); }
    return 0;
  });

  if (!entries.length) return `No listed stable versions found for ${pkg}.`;

  let chosen = null;
  let reason = '';
  for (const e of entries) {
    const groups = (e.dependencyGroups || []).map(g => normTfm(g.targetFramework));
    // No dependencyGroups at all -> no declared dependencies; treat as compatible.
    if (!groups.length || groups.includes('any')) { chosen = e; reason = 'no framework-specific dependency groups'; break; }
    const hit = groups.find(g => allowed.includes(g));
    if (hit) { chosen = e; reason = `declares a ${hit} dependency group`; break; }
  }

  if (!chosen) {
    const newest = entries[0];
    return `WARNING: no version of ${pkg} declares a dependency group compatible with ${tfm}. ` +
           `Newest stable is ${newest.version} (groups: ${(newest.dependencyGroups||[]).map(g=>normTfm(g.targetFramework)).join(', ')||'none'}). ` +
           `Do NOT pin this blindly; flag for human review.`;
  }

  const vulns = (chosen.vulnerabilities || []).map(v => `severity=${v.severity} ${v.advisoryUrl}`);
  const deps = (chosen.dependencyGroups || [])
    .filter(g => allowed.includes(normTfm(g.targetFramework)))
    .flatMap(g => (g.dependencies || []).map(dep => `${dep.id} ${dep.range}`));

  // Is it worth updating at all?
  const current = String(query.currentVersion || '').trim();

  return JSON.stringify({
    package: chosen.id || pkg,
    current_version: current || null,
    resolved_version: chosen.version,
    target_framework: tfm,
    compatible: true,
    why: reason,
    deprecated: chosen.deprecation ? (chosen.deprecation.message || 'deprecated') : null,
    vulnerabilities: vulns.length ? vulns : null,
    transitive_dependencies: deps.slice(0, 15),
    newest_stable_overall: entries[0].version,
    note: entries[0].version !== chosen.version
      ? `Newest overall (${entries[0].version}) is NOT compatible with ${tfm}; use ${chosen.version}.`
      : null
  }, null, 2);

} catch (e) {
  return `Lookup failed for ${pkg}: ${e.message}. Do not guess a version - mark it for human review.`;
}

